#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 20
#define INF 1000000000

int N, M;
int prereq[MAXN]; // bitmask of prerequisites for each shop
int dp[1<<MAXN][MAXN+1]; // dp[mask][i], i=0 means entrance

int main() {
    scanf("%d %d", &N, &M);
    memset(prereq, 0, sizeof(prereq));
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b); // a must be visited before b
        prereq[b-1] |= (1 << (a-1));
    }

    int full = (1 << N) - 1;
    for (int mask = 0; mask <= full; mask++)
        for (int i = 0; i <= N; i++)
            dp[mask][i] = INF;

    dp[0][0] = 0; // at entrance, no shops visited

    for (int mask = 0; mask < full; mask++) {
        for (int i = 0; i <= N; i++) {
            if (dp[mask][i] == INF) continue;
            int cur_pos = i; // position: 0=entrance, k=shop k
            for (int j = 0; j < N; j++) {
                if (mask & (1<<j)) continue;
                if ((prereq[j] & mask) != prereq[j]) continue;
                int new_mask = mask | (1<<j);
                int dist = abs(cur_pos - (j+1));
                if (dp[new_mask][j+1] > dp[mask][i] + dist)
                    dp[new_mask][j+1] = dp[mask][i] + dist;
            }
        }
    }

    int ans = INF;
    for (int i = 1; i <= N; i++) {
        if (dp[full][i] == INF) continue;
        int cost = dp[full][i] + (N+1-i);
        if (cost < ans) ans = cost;
    }
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 2000

// adjacency list for graph
int graph[MAX_N + 1][MAX_N + 1];
int graph_size[MAX_N + 1];
int indeg[MAX_N + 1];
int N;

// topological order
int topo[MAX_N];
int topo_size;

// Kahn's algorithm for topological sort
int topological_sort() {
    int queue[MAX_N];
    int front = 0, rear = 0;
    int i;

    for (i = 1; i <= N; i++) {
        indeg[i] = 0;
    }
    for (i = 1; i <= N; i++) {
        for (int j = 0; j < graph_size[i]; j++) {
            indeg[graph[i][j]]++;
        }
    }

    for (i = 1; i <= N; i++) {
        if (indeg[i] == 0) {
            queue[rear++] = i;
        }
    }

    topo_size = 0;
    while (front < rear) {
        int u = queue[front++];
        topo[topo_size++] = u;
        for (int j = 0; j < graph_size[u]; j++) {
            int v = graph[u][j];
            indeg[v]--;
            if (indeg[v] == 0) {
                queue[rear++] = v;
            }
        }
    }
    return (topo_size == N);
}

int main() {
    int M;
    scanf("%d %d", &N, &M);

    for (int i = 0; i <= N; i++) {
        graph_size[i] = 0;
    }

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        graph[a][graph_size[a]++] = b;
    }

    if (!topological_sort()) {
        // If there is a cycle, it's impossible to satisfy all restrictions
        // but problem guarantees feasibility? We'll output something anyway.
        // In a valid input, it should be a DAG.
    }

    // dp_forward[i] = maximum position reachable after visiting i and all its predecessors
    // dp_backward[i] = minimum position reachable after visiting i and all its predecessors (in terms of going back)
    // Actually we need to compute the minimum walking distance.
    // 
    // The optimal strategy: 
    // - We must visit shops in an order that respects the partial order.
    // - We start at position 0, end at position N+1.
    // - The walking distance is sum of absolute differences between consecutive visited positions,
    //   where we can also insert "passing through" shops without visiting.
    //
    // Known solution: The minimum walking distance = (N+1) + 2 * sum over edges (u -> v) where u > v of (u - v)
    // Because for each "backward" edge, we must go back and forth.
    //
    // More precisely: Let the topological order be p1, p2, ..., pN.
    // For each restriction a -> b, if a > b, then we must walk extra distance 2*(a - b).
    // The base distance from 0 to N+1 visiting all shops in some order is (N+1) + 2 * (sum of "backward steps").
    // But the optimal order is the topological order. The total distance = (N+1) + 2 * sum_{i=1}^{N} max(0, p_i - max_{j < i, p_j > p_i} p_j)
    // Actually simpler: For each restriction a->b, if a > b, add 2*(a-b). Then answer = N+1 + that sum.

    long long extra = 0;
    for (int u = 1; u <= N; u++) {
        for (int j = 0; j < graph_size[u]; j++) {
            int v = graph[u][j];
            if (u > v) {
                extra += 2 * (u - v);
            }
        }
    }

    long long ans = N + 1 + extra;
    printf("%lld\n", ans);

    return 0;
}

