public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] prereq = new int[N]; // bitmask of prerequisites for each shop
        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            prereq[b] |= (1 << a);
        }
        int full = (1 << N) - 1;
        int[][] dp = new int[1 << N][N];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);

        for (int i = 0; i < N; i++) {
            if (prereq[i] == 0) {
                dp[1 << i][i] = (i + 1); // distance from entrance (pos 0) to shop i+1
            }
        }

        for (int mask = 1; mask <= full; mask++) {
            for (int last = 0; last < N; last++) {
                if (dp[mask][last] == Integer.MAX_VALUE / 2) continue;
                if ((mask & (1 << last)) == 0) continue;
                // try visiting next shop
                for (int next = 0; next < N; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    if ((prereq[next] & mask) != prereq[next]) continue;
                    int newMask = mask | (1 << next);
                    int dist = dp[mask][last] + Math.abs((next + 1) - (last + 1));
                    if (dist < dp[newMask][next]) {
                        dp[newMask][next] = dist;
                    }
                }
            }
        }

        int ans = Integer.MAX_VALUE;
        for (int last = 0; last < N; last++) {
            if (dp[full][last] < Integer.MAX_VALUE / 2) {
                ans = Math.min(ans, dp[full][last] + (N + 1) - (last + 1));
            }
        }
        System.out.println(ans);
    }
}

