public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        // For each position, store the farthest shop that must be visited before it
        int[] farthestBefore = new int[N + 2];
        for (int i = 1; i <= N; i++) {
            farthestBefore[i] = i;
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            // a must be visited before b
            // If a > b, then we must go to a before we can finally pass b going forward
            if (a > b) {
                farthestBefore[b] = Math.max(farthestBefore[b], a);
            }
        }

        // Propagate constraints: if we need to reach far point before b,
        // we also need it before any point after b
        int currentFarthest = 0;
        long totalDistance = 0;
        int currentPos = 0;

        for (int pos = 1; pos <= N + 1; pos++) {
            currentFarthest = Math.max(currentFarthest, farthestBefore[pos]);

            if (pos == currentFarthest) {
                // We need to go to this point, then come back
                totalDistance += (long)(pos - currentPos) * 2;
                currentPos = pos;
            }
        }

        // Add the final distance to exit
        totalDistance += (long)(N + 1 - currentPos);

        System.out.println(totalDistance);

        br.close();
    }
}

