/*
Core idea:
- She walks on a line from entrance at 0 to exit at N+1.
- Without any restrictions, minimum walking length is N+1.
- A restriction a -> b means shop a must be visited before shop b.
- If a < b, this causes no extra walking because she can visit in forward order.
- If a > b, then to visit a before b on a line, she must at some point go right to at least a and later come back left to b.
  This creates backtracking.

We model only the "backward" constraints a > b as intervals [b, a].
If two such intervals overlap/cross, they can be handled within one backtracking excursion whose extra cost is
2 * (maxRight - minLeft).
If they are disjoint, their extra costs add independently.

Therefore:
1) Collect intervals [min=b, max=a] for all constraints a > b.
2) Sort by left endpoint.
3) Merge overlapping intervals.
4) Answer = (N+1) + sum over merged intervals of 2 * (R-L).

Why merging works:
Any overlapping backward requirements can be satisfied during one detour covering the whole union interval.
Non-overlapping ones require separate detours.

This is enough because forward constraints never hurt, and any topological ordering inside each covered region can be arranged.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Interval {
        int l, r;
        Interval(int l, int r) {
            this.l = l;
            this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        ArrayList<Interval> intervals = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            if (a > b) {
                intervals.add(new Interval(b, a));
            }
        }

        long answer = (long) N + 1;

        if (!intervals.isEmpty()) {
            intervals.sort((x, y) -> {
                if (x.l != y.l) return Integer.compare(x.l, y.l);
                return Integer.compare(x.r, y.r);
            });

            int curL = intervals.get(0).l;
            int curR = intervals.get(0).r;

            for (int i = 1; i < intervals.size(); i++) {
                Interval in = intervals.get(i);
                if (in.l <= curR) {
                    curR = Math.max(curR, in.r);
                } else {
                    answer += 2L * (curR - curL);
                    curL = in.l;
                    curR = in.r;
                }
            }
            answer += 2L * (curR - curL);
        }

        System.out.println(answer);
    }
}

