#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // Build adjacency list for constraints
    vector<vector<int>> before(N + 1);  // before[a] = shops that must be visited before a
    vector<int> indegree(N + 1, 0);

    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        before[a].push_back(b);
        indegree[b]++;
    }

    // Topological sort to get valid order
    vector<int> topo;
    queue<int> q;
    for (int i = 1; i <= N; i++) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        topo.push_back(u);

        for (int v : before[u]) {
            indegree[v]--;
            if (indegree[v] == 0) {
                q.push(v);
            }
        }
    }

    // DP approach: For each shop, compute min distance to reach it
    // and satisfy all constraints up to that point
    const int INF = 1e9;
    vector<int> dp(N + 1, INF);
    dp[0] = 0;

    // We process shops in topological order and also consider positions
    // The optimal strategy involves going from left to right, possibly with backtracking

    // For each position, we maintain the best way to reach it
    // Considering we can go forward or backward

    // Let's use a different approach: compute min distance for each possible
    // "current position" after visiting some set of shops

    // Since N <= 2000, we can use O(N^2) DP
    // dp[i][j] = min distance to have visited all shops up to position i,
    // and currently be at position j (j <= i+1, where j=0 means entrance)

    // Actually, let's simplify: The optimal path is a sequence of visits
    // We can think of it as: we must visit shops in some order respecting constraints
    // The minimal path is like: go right, go back left to satisfy constraints, go right again, etc.

    // For each shop, we need to know the farthest shop that must be visited before it
    // and the nearest shop that must be visited after it

    // Build transitive closure of constraints
    vector<vector<bool>> mustVisitBefore(N + 2, vector<bool>(N + 2, false));
    for (int i = 1; i <= N; i++) {
        for (int v : before[i]) {
            mustVisitBefore[i][v] = true;
        }
    }

    // Floyd-Warshall for transitive closure
    for (int k = 1; k <= N; k++) {
        for (int i = 1; i <= N; i++) {
            if (mustVisitBefore[i][k]) {
                for (int j = 1; j <= N; j++) {
                    if (mustVisitBefore[k][j]) {
                        mustVisitBefore[i][j] = true;
                    }
                }
            }
        }
    }

    // For each shop, find the farthest shop that must be visited before it
    vector<int> farthestBefore(N + 2, 0);
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            if (mustVisitBefore[i][j]) {
                farthestBefore[i] = max(farthestBefore[i], j);
            }
        }
    }

    // dp[i] = minimum distance to have visited shops 1..i and be at position i
    vector<int> dp_forward(N + 2, INF);
    dp_forward[0] = 0;

    for (int i = 1; i <= N; i++) {
        // To reach position i, we need to have visited all shops that must be before i
        // The farthest such shop determines how far back we might need to go

        int needToVisit = farthestBefore[i];

        // We can come from any position j < i
        for (int j = 0; j < i; j++) {
            if (dp_forward[j] < INF) {
                // We need to go from j to i, possibly passing through shops
                // If needToVisit > j, we must have already visited those shops
                if (needToVisit <= j) {
                    dp_forward[i] = min(dp_forward[i], dp_forward[j] + (i - j));
                } else {
                    // We need to go back to visit shops j+1..needToVisit first
                    dp_forward[i] = min(dp_forward[i], dp_forward[j] + (needToVisit - j) + (i - needToVisit));
                }
            }
        }
    }

    // After visiting all shops, we need to go to exit at N+1
    int answer = INF;
    for (int i = 0; i <= N; i++) {
        if (dp_forward[i] < INF) {
            answer = min(answer, dp_forward[i] + (N + 1 - i));
        }
    }

    cout << answer << "\n";

    return 0;
}

