static const long long INFLL = (1LL<<60);
static const int INF = 1e9;

struct SegTree {
    int n;
    vector<long long> st;
    SegTree(int sz=0){ init(sz); }
    void init(int sz){
        n=1;
        while(n<sz) n<<=1;
        st.assign(2*n, INFLL);
    }
    void setval(int p, long long v){
        p += n;
        st[p]=v;
        for(p>>=1; p; p>>=1) st[p]=min(st[p<<1], st[p<<1|1]);
    }
    long long query(int l, int r){
        if(l>r) return INFLL;
        l += n; r += n;
        long long res=INFLL;
        while(l<=r){
            if(l&1) res=min(res, st[l++]);
            if(!(r&1)) res=min(res, st[r--]);
            l>>=1; r>>=1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<int> outMin(N+1, INF);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        outMin[u] = min(outMin[u], v);
    }

    vector<long long> dp(N+1, INFLL);
    SegTree seg(N+1);
    dp[0] = 0;
    seg.setval(0, 0);

    // intervals: pair(left_boundary, value), covering j in [0..i-1]
    vector<pair<int,int>> intervals;

    for (int i = 1; i <= N; ++i) {
        int a = outMin[i];
        int left = i-1;
        while (!intervals.empty() && intervals.back().second >= a) {
            left = intervals.back().first;
            intervals.pop_back();
        }
        intervals.push_back({left, a});

        long long best = INFLL;
        for (int idx = 0; idx < (int)intervals.size(); ++idx) {
            int l = intervals[idx].first;
            int r = (idx + 1 < (int)intervals.size() ? intervals[idx+1].first - 1 : i - 1);
            int t = intervals[idx].second;

            if (t == INF) {
                best = min(best, seg.query(l, r));
            } else {
                int r1 = min(r, t - 1);
                if (l <= r1) best = min(best, seg.query(l, r1));
                int l2 = max(l, t);
                if (l2 <= r) best = min(best, seg.query(l2, r) + 2LL * (i - t));
            }
        }

        dp[i] = best;
        seg.setval(i, dp[i]);
    }

    cout << (N + 1LL + dp[N]) << '\n';
    return 0;
}
